mapper.select:
SELECT MIN(board_id)
  FROM board
 WHERE company_id = #{companyId}
   AND board_type = 'BOARD_DEPT'
   AND department_id = #{departmentId}
   AND use_yn = 'Y'

mapper.sql:
WHERE company_id = #{companyId}
  AND post_id = #{postId}
  AND author_employee_id = #{authorId}
  AND deleted_at IS NULL
  AND board_id IN (SELECT board_id FROM board
                    WHERE company_id = #{companyId}
                      AND board_type = 'BOARD_DEPT'
                      AND department_id = #{departmentId})
